import type {
  FileContents,
  FileDiffMetadata,
  ParseDiffOptions,
} from '../types';
import { composeCacheKey } from './composeCacheKey';
import { diffLibs, resolveDiffLib } from './diffLibs';
import { processFile } from './parsePatchFiles';

const MISSING_FILE_NAME = '/dev/null';

/**
 * Parses a diff from two file contents objects.
 *
 * If both `oldFile` and `newFile` have a `cacheKey`, the resulting diff gets a
 * collision-safe key derived from both values and the line-matching mode.
 */
export function parseDiffFromFile(
  oldFile: FileContents | null,
  newFile: FileContents | null,
  {
    preferredDiffLib = 'jsdiff',
    disableLineMatching,
    ...diffOptions
  }: ParseDiffOptions = {},
  throwOnError = false
): FileDiffMetadata {
  if (oldFile === null && newFile === null) {
    throw new Error(
      'parseDiffFromFile: You must pass oldFile, newFile, or both'
    );
  }

  const resolvedOldFile = oldFile ?? createMissingFile();
  const resolvedNewFile = newFile ?? createMissingFile();
  const patchArgs = [
    resolvedOldFile.name,
    resolvedNewFile.name,
    resolvedOldFile.contents,
    resolvedNewFile.contents,
    resolvedOldFile.header,
    resolvedNewFile.header,
    diffOptions,
  ] as const;
  const diffLib = throwOnError
    ? preferredDiffLib
    : resolveDiffLib(preferredDiffLib);
  let patch: string;
  try {
    patch = diffLibs[diffLib].createTwoFilesPatch(...patchArgs);
  } catch (error) {
    // Wasm can run out of memory where jsdiff works.
    if (throwOnError || diffLib === 'jsdiff') {
      throw error;
    }
    console.error(error);
    patch = diffLibs.jsdiff.createTwoFilesPatch(...patchArgs);
  }

  const fileData = processFile(patch, {
    cacheKey: (() => {
      const oldCacheKey = oldFile?.cacheKey;
      const newCacheKey = newFile?.cacheKey;
      return oldCacheKey != null && newCacheKey != null
        ? composeCacheKey(
            disableLineMatching === true ? 'diff-raw' : 'diff',
            oldCacheKey,
            newCacheKey
          )
        : undefined;
    })(),
    oldFile: resolvedOldFile,
    newFile: resolvedNewFile,
    disableLineMatching,
    throwOnError,
  });
  if (fileData == null) {
    throw new Error(
      'parseDiffFrom: FileInvalid diff -- probably need to fix something -- if the files are the same maybe?'
    );
  }
  if (oldFile === null) {
    fileData.type = 'new';
    fileData.prevName = undefined;
  } else if (newFile === null) {
    fileData.type = 'deleted';
    fileData.prevName = undefined;
  }
  // If we've been provided an override for language in the newFile, let’s pass
  // it through to FileDiffMetadata.
  const language =
    newFile?.lang ?? (newFile === null ? oldFile?.lang : undefined);
  if (language != null) {
    fileData.lang = language;
  }
  return fileData;
}

function createMissingFile(): FileContents {
  return { name: MISSING_FILE_NAME, contents: '' };
}
